using UnityEngine;using UnityEngine.Rendering.HighDefinition;
public static class CaptureGauge{public static string Main(){var gauge=Object.FindFirstObjectByType<MotorollerSpeedometer>();var go=new GameObject("Gauge preview camera"){hideFlags=HideFlags.HideAndDontSave};var camera=go.AddComponent<Camera>();camera.enabled=false;go.AddComponent<HDAdditionalCameraData>();camera.fieldOfView=40;camera.nearClipPlane=.005f;go.transform.position=gauge.transform.position-gauge.transform.forward*.23f;go.transform.rotation=Quaternion.LookRotation(gauge.transform.forward,gauge.transform.up);var rt=RenderTexture.GetTemporary(1000,800,24);var previous=RenderTexture.active;var image=new Texture2D(1000,800,TextureFormat.RGB24,false);try{camera.targetTexture=rt;camera.Render();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1000,800),0,0);image.Apply();System.IO.File.WriteAllBytes("output/Motoroller/Speedometer.png",image.EncodeToPNG());return "Captured gauge";}finally{camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(image);Object.DestroyImmediate(go);}}}

